import type {
	PrepaintOptions,
	SavedAppearance,
} from "@aomc-server/block-ui/theme";

/**
 * The inline script of index.html (generated by `prepaintScript` in vite.config.ts) applies the
 * saved appearance before the first paint. The map is not loaded yet, so the palette is the one
 * last shown for the same dimension (theme.ts `savePalette`).
 */
export const prepaint: PrepaintOptions = {
	storageKey: "blockmap.settings",
	palettes: ["overworld", "nether", "end", "unknown"],
	defaults: { mode: "dark", style: "bedrock", palette: "overworld" },
	// Serialised into the page: it may only use its own arguments. The keys are SETTINGS_KEY in
	// settings.ts and PALETTE_KEY in theme.ts.
	reader: (stored, ctx) => {
		const s = stored || {};
		const result: SavedAppearance = {
			mode: s.mode,
			style: s.style,
		};
		try {
			const p = JSON.parse(ctx.storage.getItem("blockmap.palette") || "null");
			const dim = new URLSearchParams(ctx.location.search).get("dim");
			// Same pages as main.tsx; everything else is the map.
			const path = ctx.location.pathname.replace(/\/+$/, "");
			const onMap =
				!/^\/invite\/[^/?#]+\/?$/.test(ctx.location.pathname) &&
				path !== "/settings" &&
				path !== "/manage" &&
				path !== "/stats";
			if (p && onMap && s.dimensionColours !== false && (!dim || dim === p.dim))
				result.palette = p.palette;
		} catch {}
		return result;
	},
};
